type Props={club:ClubAccount;session:AuthSession;onBack:()=>void;onWhiteboard:()=>void}
type SheetPlayer={id:string;clubPlayerId:string;playerName:string;jumperNumber:number|null;positionCode:string}
type Sheet={id:string;fixtureId:string|null;roundLabel:string;opponentName:string|null;matchDate:string|null;status:string;players:SheetPlayer[]}
type Fixture={id:string;homeClubId:string;homeClubName:string;awayClubId:string;awayClubName:string;homeClubLogoUrl?:string|null;awayClubLogoUrl?:string|null;homeLogoUrl?:string|null;awayLogoUrl?:string|null;homeLogo?:string|null;awayLogo?:string|null}
type TeamVisual={logoUrl:string|null;coverPhotoUrl:string|null}
type PlayerSlot={clubPlayerId:string;playerName:string;jumperNumber:number|null;positionCode:string;onGround:boolean;plusMinus:number;goals:number;behinds:number;onGroundSeconds:number;benchSeconds:number;benchEnteredAt:number|null;fresh:boolean;injured:boolean}
type Event={id:string;quarter:number;seconds:number;kind:'SCORE'|'SWAP'|'QUARTER'|'STAT'|'INJURY'|'RESET';label:string}
type StatKey='inside50s'|'clearances'|'tackles'|'marks'|'rebound50s'|'onePercenters'|'freesAgainst'
type TeamStats=Record<StatKey,number>
type ScoreUndo={homeGoals:number;homeBehinds:number;awayGoals:number;awayBehinds:number;slots:Array<Pick<PlayerSlot,'clubPlayerId'|'goals'|'behinds'|'plusMinus'>>}
type MatchState={sheetId:string;quarter:number;elapsed:number;runningSince:number|null;homeGoals:number;homeBehinds:number;awayGoals:number;awayBehinds:number;slots:PlayerSlot[];events:Event[];totalTrackedSeconds:number;trackingUpdatedAt:number|null;teamStats:TeamStats;kpiTargets:TeamStats;scoreUndo:ScoreUndo[]}
