function MatchClock({state,seconds,portrait,onClock,onNextQuarter,onUndo,onReset}:{state:MatchState;seconds:number;portrait:boolean;onClock:()=>void;onNextQuarter:()=>void;onUndo:()=>void;onReset:()=>void}){return <View style={[styles.clock,portrait&&styles.clockPortrait]}><Text style={styles.quarter}>QUARTER {state.quarter}</Text><Text style={[styles.time,portrait&&styles.timePortrait]}>{formatTime(seconds)}</Text><View style={styles.clockActions}><Pressable onPress={onClock} style={[styles.clockButton,Boolean(state.runningSince)&&styles.pauseButton]}>{state.runningSince?<Pause size={12} color="#05130B"/>:<Play size={12} color="#05130B"/>}<Text style={styles.clockButtonText}>{state.runningSince?'Pause':'Start'}</Text></Pressable><Pressable disabled={state.quarter>=4} onPress={onNextQuarter} style={[styles.nextButton,state.quarter>=4&&styles.disabled]}><SkipForward size={12} color="#fff"/><Text style={styles.nextText}>Q{Math.min(4,state.quarter+1)}</Text></Pressable><Pressable disabled={!state.scoreUndo.length} onPress={onUndo} style={[styles.undoButton,!state.scoreUndo.length&&styles.disabled]}><Text style={styles.undoText}>Undo</Text></Pressable><Pressable onPress={onReset} style={styles.resetButton}><RefreshCw size={10} color="#fff"/><Text style={styles.resetText}>Reset</Text></Pressable></View></View>}
